import { ref } from 'vue';

export function useHover() {
  const isHovered = ref(false);

  const hoverEffect = () => {
    isHovered.value = true;
  };

  const removeEffect = () => {
    isHovered.value = false;
  };

  return {
    isHovered,
    hoverEffect,
    removeEffect
  };
}
