<template>
  <v-app>
    <v-main>
      <router-view/>
    </v-main>
  </v-app>

</template>

<script>
export default {
  name: 'App',

  data: () => ({
    // 여기서 다른 데이터가 있다면 추가할 수 있습니다.
  }),

  mounted() {
    const titles = ['Welcome', 'Thanks for Visiting', "Mangyu's Portfolio"];
    let currentIndex = 0;

    // 타이틀을 주기적으로 변경
    setInterval(() => {
      document.title = titles[currentIndex];
      currentIndex = (currentIndex + 1) % titles.length;
    }, 3500); 
  }
}
</script>

